options.getOption:
let newPanelValues = [], originalPanelValues = [];

context.panel.data.series.forEach((s) => {
  if (s.refId === 'C') {
    timeData = s.fields.find(f => f.name === 'Time')?.values ?? [];
    newPanelValues = s.fields.find(f => f.name === 'C')?.values ?? [];
  } else if (s.refId === 'D') {
    originalPanelValues = s.fields.find(f => f.name === 'D')?.values ?? [];
  }
});

// Calculate total daily consumption
let totalMonthlyPowerConsumption = [];
for (let i = 0; i < timeData.length; i++) {
  let total = 0;
  total += newPanelValues[i] || 0;
  total += originalPanelValues[i] || 0;
  totalMonthlyPowerConsumption.push(total);
}

// Format dates
const formattedDates = timeData.map(d => {
  const date = new Date(d); // Parse the ISO string directly
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + 1; // Month is zero-indexed
  const day = date.getUTCDate();
  let hour = date.getUTCHours() + 4; // Adjust the hour by 4 to account for your timezone
  const minute = date.getUTCMinutes();

  // Determine AM/PM and adjust hour for 12-hour format
  const ampm = hour >= 12 ? 'PM' : 'AM';
  hour = hour % 12;
  hour = hour ? hour : 12; // If hour is 0, set it to 12

  // Return formatted date string as 'MM/DD/YYYY'
  return `${month}/${day}/${year}`;
});

// Check if the time range exceeds one year
const firstDate = new Date(timeData[0]);
const lastDate = new Date(timeData[timeData.length - 1]);
const oneYearInMs = 365 * 24 * 60 * 60 * 1000; // Approximate milliseconds in one year
const timeRangeExceedsOneYear = (lastDate - firstDate) > oneYearInMs;

// If time range exceeds one year, don't display values on top of bars
const showLabel = !timeRangeExceedsOneYear;

return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'cross'
    }
  },
  legend: {
    data: ['New Panel', 'Original Panel']
  },
  grid: {
    left: '5%',
    right: '4%',
    bottom: '10%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: formattedDates,
    axisLabel: {
      formatter: function (val) {
        const date = new Date(val);
        const month = date.getMonth() + 1; // Month is zero-indexed
        const day = date.getDate();
        return `${month}/${day}`;
      }
    }
  },
  yAxis: {
    type: 'value',
    name: 'Monthly Power Consumption',
    nameLocation: 'middle',
    nameGap: 70,
    nameTextStyle: {
      fontSize: 12,
      align: 'center',
      verticalAlign: 'middle',
    }
  },
  series: [
    {
      name: 'New Panel',
      type: 'bar',
      stack: 'total',
      data: newPanelValues,
      itemStyle: {
        color: '#5fb4f5' // Set the color to blue
      }
    },
    {
      name: 'Original Panel',
      type: 'bar',
      stack: 'total',
      data: originalPanelValues,
      itemStyle: {
        color: '#f5de49' // Set the color to yellow
      },
      // Only show label if the time range is within one year
      label: showLabel ? {
        show: true,
        position: 'top',
        formatter: function (params) {
          return totalMonthlyPowerConsumption[params.dataIndex].toFixed(2); // Format to 2 decimal places
        },
      } : {}
    }
  ]
};

